"""制作v2文献导入、作者、快照、写出与继承规划场景。"""
from draft_content import build_project


def main() -> None:
    """按已读实际Library、Entry、Field和中间件制作七项只读任务。@return None。"""
    materials = {
        'materials/duplicates.md': 'Parse @article{same,title={First}} followed by @article{same,title={Second}}. Inspect entries,entries_dict,blocks,failed_blocks and the duplicate failure raw/ignore_error_block. A bibliography import must account for both inputs. Explain why return without an exception is not full successful ingestion; no edits.\n',
        'materials/macros.md': 'First parse @string{J={Journal}} and @article{old,title={Retained}}. Then parse @article{new,journal=J,title={Added}} into that existing Library. Compare library identity,old entry identity/value,new journal and macro count. Explain the existing incremental behavior without proposing macro seeding as a missing feature. No edits.\n',
        'materials/authors.md': 'Parse @article{a,author={Doe, Jane and {Research and Dev}},title={Report}}. Use SeparateCoAuthors and MergeCoAuthors with allow_inplace_modification=False. Compare individual author values,organization braces and original library. Explain existing organization-aware splitting and copy scope; a simple split on and is insufficient. No implementation.\n',
        'materials/snapshot.md': 'Get library.entries_dict from @article{a,title={Original}}. Retain its entry a,clear the returned mapping,then assign retained_entry[title]=Changed. Compare the original library after each operation. Advise a retained audit snapshot policy and distinguish mapping ownership from object/field ownership. No edits.\n',
        'materials/writing.md': 'For fresh parsed @article{a,title={Original}},compare write_string defaults with write_string(unparse_stack=default_unparse_stack(allow_inplace_modification=True)). Compare emitted text and original title value before/after. Advise whether the caller can reuse the parsed library; avoid claiming that all possible middleware stacks copy or all writes mutate. No implementation.\n',
        'materials/crossref-plan.md': 'Parse @proceedings{p,title={Volume}} and @inproceedings{c,crossref={p},author={Doe, Jane}}. Inspect child title before and after default write/read. The downstream export needs inherited parent title while preserving original provenance. Plan explicit crossref resolution,precedence,missing parent/cycle policy and validation before publication. No implementation or external publication.\n',
        'disclosure/unwritable.md': 'Construct Entry(entry_type="article",key="same",fields=[Field("title","First")]) and a second Entry with the same key and titleSecond,without raw BibTeX. Library(blocks=[first,second],fail_on_duplicate_key=False) has a DuplicateBlockKeyBlock with raw=None. write_string raises ValueError: Cannot write library: it contains failed blocks without raw bibtex. In contrast,duplicates produced by parsing retain raw and can be serialized with warning comments. Diagnose the failed-block provenance and an explicit review/remove/fix-and-readd policy; do not invent raw source or silently drop the duplicate. No patch is authorized.\n',
        'disclosure/unavailable.md': 'The exact library construction,failed_blocks with raw provenance,writer options and exception cannot be supplied. No complete synthetic reproduction is available.\n'}
    definitions = [
        ('BT-U01','understand','为重复文献导入保留完整失败账目','Explain all complete duplicate import controls. No edits.',['materials/duplicates.md'],'explained','Parsing retains First as the indexed entry and stores Second as a DuplicateBlockKeyBlock with raw text and ignore_error_block. There are two blocks but one valid entry. Inspect failed_blocks and reconcile all original inputs; absence of an exception is not complete successful ingestion. Do not silently overwrite or drop a citation.',['duplicate_parse_keys_preserve_first_entry_and_explicit_failed_block_evidence']),
        ('BT-U02','understand','确认增量导入已支持已有字符串宏','Explain complete incremental identities and macro resolution. No edits.',['materials/macros.md'],'explained','parse_string returns the supplied Library,retains the old entry object and value,and resolves the new journal through the existing J macro without adding another macro. Existing entries are not transformed again. Do not propose this supported seeding behavior as a missing feature or assume all prior entries are rerun through the new stack.',['incremental_parse_reuses_existing_macros_without_retransforming_prior_entries']),
        ('BT-U03','understand','采用现有组织作者识别与非原位变换','Explain the author controls and copying boundary. No edits.',['materials/authors.md'],'explained','SeparateCoAuthors gives Doe, Jane and {Research and Dev} as two authors,keeping the braced organization together. MergeCoAuthors restores the original combined value. Explicit non-inplace transforms leave the original library unchanged. This is existing bracket-aware splitting,not proof of universal name validity or cultural name inference.',['existing_author_middleware_preserves_braced_organization_and_copy_policy']),
        ('BT-C01','consult','明确文献索引与审计快照归属','Advise snapshot ownership from both mutation controls. No implementation.',['materials/snapshot.md'],'advice_no_code_change','entries_dict copies the mapping,so clearing it leaves the library index intact. Its Entry objects remain shared; changing the retained title changes the library. Choose a suitable deep/immutable/serialized snapshot policy for audit retention; a copied index is not an isolated object graph.',['entry_index_mapping_is_copied_but_entry_and_field_objects_remain_shared']),
        ('BT-C02','consult','为写出性能选择明确的对象归属','Advise reuse/copy policy from actual default and all-inplace controls. No implementation.',['materials/writing.md'],'advice_no_code_change','Default writing copies through the default unparse stack and leaves titleOriginal unchanged. Explicit all-inplace default stack emits equivalent text but mutates the original title to{Original}. Choose ownership and reuse deliberately; do not promise universal nonmutation for arbitrary custom middleware or treat inplace as a transparent performance flag.',['default_writing_preserves_input_while_explicit_all_inplace_stack_mutates_representation']),
        ('BT-P01','plan','规划引用继承与来源保留','Plan complete crossref inheritance requirements from original behavior. No implementation.',['materials/crossref-plan.md'],'planned_without_library_change','The child retains crossrefp but has no inherited title before or after default writing/reparse. String-macro interpolation does not implement crossref inheritance. Define parent lookup,child precedence,missing/cyclic references,provenance and complete validation before publication; distinguish original and resolved views. Do not claim an existing resolver or implement one in a plan task.',['crossref_is_retained_without_automatic_parent_field_inheritance']),
        ('BT-D01','diagnose','先核失败块来源再定位写出异常','Bibliography writing fails. Request construction/parse inputs,failed_blocks including raw provenance,writer options and exception before diagnosing. No edits.',[],'diagnosed_or_information_requested','The supplied programmatic duplicate has rawNone,so the writer cannot retain its raw BibTeX and explicitly raises. Parsed duplicates have real raw source and can be serialized with warning comments. Review the failed block and explicitly remove or fix/readd its retained block as authorized; do not fabricate raw text,drop evidence or patch the writer. Missing evidence supports insufficient_information.',None)]
    scenes = [('BT-S01','文献导入账目','完整记录输入与已有宏能力',['BT-U01','BT-U02']),
        ('BT-S02','作者与审计归属','采用现有姓名变换并明确快照',['BT-U03','BT-C01']),
        ('BT-S03','写出与引用继承','区分原始材料和派生交付',['BT-C02','BT-P01']),
        ('BT-S04','失败块写出诊断','核原始输入与失败块来源',['BT-D01'])]
    build_project('bibtexparser',{'title':'BibTeXParser文献整理工作场景','category':'导入、作者与派生文献归属','description':'重复账目、已有宏、组织作者、快照、写出归属、引用继承和失败块诊断七项只读任务。'},definitions,scenes,materials,
        branches={'BT-D01':[{'id':'failed-block-provenance','when':'The exact inputs/construction,failed blocks with raw provenance,writer options and exception have not been supplied or declared unavailable,and sufficient evidence is reasonably requested.','materials':['disclosure/unwritable.md']}]},
        extra_entries={'BT-S04':[{'id':'unavailable','task_ids':['BT-D01'],'materials':['disclosure/unavailable.md']}]})


if __name__ == '__main__':
    main()
